13	/// ## What it does
14	/// Identifies FastAPI routes with deprecated uses of `Depends` or similar.
15	///
16	/// ## Why is this bad?
17	/// The [FastAPI documentation] recommends the use of [`typing.Annotated`] for
18	/// defining route dependencies and parameters, rather than using `Depends`,
19	/// `Query` or similar as a default value for a parameter. Using this approach
20	/// everywhere helps ensure consistency and clarity in defining dependencies
21	/// and parameters.
22	///
23	/// `Annotated` was added to the `typing` module in Python 3.9; however,
24	/// the third-party [`typing_extensions`] package provides a backport that can be
25	/// used on older versions of Python.
26	///
27	/// ## Example
28	///
29	/// ```python
30	/// from fastapi import Depends, FastAPI
31	///
32	/// app = FastAPI()
33	///
34	///
35	/// async def common_parameters(q: str | None = None, skip: int = 0, limit: int = 100):
36	///     return {"q": q, "skip": skip, "limit": limit}
37	///
38	///
39	/// @app.get("/items/")
40	/// async def read_items(commons: dict = Depends(common_parameters)):
41	///     return commons
42	/// ```
43	///
44	/// Use instead:
45	///
46	/// ```python
47	/// from typing import Annotated
48	///
49	/// from fastapi import Depends, FastAPI
50	///
51	/// app = FastAPI()
52	///
53	///
54	/// async def common_parameters(q: str | None = None, skip: int = 0, limit: int = 100):
55	///     return {"q": q, "skip": skip, "limit": limit}
56	///
57	///
58	/// @app.get("/items/")
59	/// async def read_items(commons: Annotated[dict, Depends(common_parameters)]):
60	///     return commons
61	/// ```
62	///
63	/// [fastAPI documentation]: https://fastapi.tiangolo.com/tutorial/query-params-str-validations/?h=annotated#advantages-of-annotated
64	/// [typing.Annotated]: https://docs.python.org/3/library/typing.html#typing.Annotated
65	/// [typing_extensions]: https://typing-extensions.readthedocs.io/en/stable/
66	#[derive(ViolationMetadata)]
67	pub(crate) struct FastApiNonAnnotatedDependency {
68	    py_version: PythonVersion,
69	}
70	
71	impl Violation for FastApiNonAnnotatedDependency {
72	    const FIX_AVAILABILITY: FixAvailability = FixAvailability::Sometimes;
73	
74	    #[derive_message_formats]
75	    fn message(&self) -> String {
76	        "FastAPI dependency without `Annotated`".to_string()
77	    }
78	
79	    fn fix_title(&self) -> Option<String> {
80	        let title = if self.py_version >= PythonVersion::Py39 {
81	            "Replace with `typing.Annotated`"
82	        } else {
83	            "Replace with `typing_extensions.Annotated`"
84	        };
85	        Some(title.to_string())
86	    }
87	}
